function openMenu(b,n){const l=$('#menuLayer');l.innerHTML='';menu(n).forEach(i=>{if(i==='sep'){const d=document.createElement('div');d.className='menu-separator';l.appendChild(d);return}const x=document.createElement('button');x.className='menu-item';x.innerHTML='<span>'+i[0]+'</span><span class="shortcut">'+i[1]+'</span>';x.onclick=()=>{closeMenu();i[2]()};l.appendChild(x)});const r=b.getBoundingClientRect();l.style.left=Math.min(r.left,innerWidth-215)+'px';l.style.top=(r.bottom+2)+'px';l.classList.remove('hidden');b.classList.add('open')}
