wrap.addEventListener('dragenter',e=>{e.preventDefault();wrap.classList.add('drag-hover')});wrap.addEventListener('dragover',e=>{e.preventDefault();wrap.classList.add('drag-hover')});wrap.addEventListener('dragleave',e=>{if(!wrap.contains(e.relatedTarget))wrap.classList.remove('drag-hover')});wrap.addEventListener('drop',e=>{e.preventDefault();wrap.classList.remove('drag-hover');handleDrop(e.dataTransfer?.files||[])});
