addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;const c=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(c&&k==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if(c&&k==='y')redo();else if(c&&k==='s'){e.preventDefault();saveProject()}else if(c&&k==='o'){e.preventDefault();pick('.blendweb,.json',fs=>loadProject(fs[0]))}else if(c&&k==='n'){e.preventDefault();newProject()}else if(c&&k==='j'){e.preventDefault();joinSelected()}else if(c&&k==='a'){e.preventDefault();applyTransforms()}else if(e.altKey&&k==='h'){e.preventDefault();unhideAll()}else if(e.altKey&&k==='a'){e.preventDefault();deselectAll()}else if(k==='a'){e.preventDefault();selectAll()}else if(k==='h'){e.preventDefault();hideSelected()}else if(k==='f'){e.preventDefault();frame()}else if(e.key==='Tab'){e.preventDefault();toggleEdit()}else if(e.key==='Delete'||e.key==='Backspace'||k==='x'){e.preventDefault();remove()}else if(e.shiftKey&&k==='d')duplicate();else if(k==='g')setTool('translate');else if(k==='r')setTool('rotate');else if(k==='s')setTool('scale');else if(k==='q')setTool('select');else if(k==='l')toggleSpace();else if(e.key==='1')view('front');else if(e.key==='3')view('right');else if(e.key==='7')view('top')});
